import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class AnotherClass {
    // Should not match: different collection type for synchronized set
    protected static Set<Integer> otherSyncSet = Collections.synchronizedSet(new TreeSet<>());
    // Should not match: synchronizedList
    protected static List<String> syncList = Collections.synchronizedList(new ArrayList<>());
    // Should not match: plain HashSet
    protected static Set<String> plainSet = new HashSet<>();
    // Should not match: already using ConcurrentHashMap.newKeySet()
    protected static Set<String> modernSet = ConcurrentHashMap.newKeySet();
}
